    ('1606817022', 40.0, 0.0, 0.0, 0.0, 23.0, false, 0.0, 0.0, 9.0, 2.0, 2.0, 2.0, 100.0, 12.83, 19.71, 64.43, 1.79, 6.92, 96.56, 58.76, 4, array['water']),
    ('1606817023', 28.0, 1.0, 0.0, 0.0, 20.0, true, 0.0, 0.0, 12.5, 1.17, 16.0, 100.0, 100.0, 12.83, 19.71, 64.43, 1.79, 6.92, 96.56, 58.76, 1, '{}'::text[]),
    ('1606818006', 100.0, 18.0, 0.0, 0.0, 33.0, true, 0.0, 0.0, 82.0, 0.0, 18.0, 100.0, 85.0, 12.83, 19.71, 64.43, 1.79, 6.92, 96.56, 58.76, 0, '{}'::text[]),
