insert into fact_uuc_phc_indicators (
  dataset_id, geo_code, physical_factor, ip_pop, armed_conf, idp, four_ps, elcac_brgy, imr, ufmr, fic, abr, pre_natal, sba, water, imr_prov_ref, ufmr_prov_ref, fic_prov_ref, abr_prov_ref, pre_natal_prov_ref, sba_prov_ref, water_prov_ref, health_indicators, capped_indicators
)
select
  (select dataset_id from ds),
  map_psgc_to_dim_geo(src.source_geo_code, 'post-2024 Sulu transfer (Sulu under Region IX)'),
  src.physical_factor, src.ip_pop, src.armed_conf, src.idp, src.four_ps, src.elcac_brgy, src.imr, src.ufmr, src.fic, src.abr, src.pre_natal, src.sba, src.water, src.imr_prov_ref, src.ufmr_prov_ref, src.fic_prov_ref, src.abr_prov_ref, src.pre_natal_prov_ref, src.sba_prov_ref, src.water_prov_ref, src.health_indicators,
  src.capped_indicators
from src
on conflict (dataset_id, geo_code) do update set
  physical_factor = excluded.physical_factor,
  ip_pop = excluded.ip_pop,
  armed_conf = excluded.armed_conf,
  idp = excluded.idp,
  four_ps = excluded.four_ps,
  elcac_brgy = excluded.elcac_brgy,
  imr = excluded.imr,
  ufmr = excluded.ufmr,
  fic = excluded.fic,
  abr = excluded.abr,
  pre_natal = excluded.pre_natal,
  sba = excluded.sba,
  water = excluded.water,
  imr_prov_ref = excluded.imr_prov_ref,
  ufmr_prov_ref = excluded.ufmr_prov_ref,
  fic_prov_ref = excluded.fic_prov_ref,
  abr_prov_ref = excluded.abr_prov_ref,
  pre_natal_prov_ref = excluded.pre_natal_prov_ref,
  sba_prov_ref = excluded.sba_prov_ref,
  water_prov_ref = excluded.water_prov_ref,
  health_indicators = excluded.health_indicators,
  capped_indicators = excluded.capped_indicators;

-- The provincial benchmarks are stored per barangay and exposed one-row-per-province by
-- the ref_uuc_phc_provincial view. That is only sound while every barangay in a province
-- carries the same reference, which the source does but nothing enforces. Assert it here:
-- a contradiction aborts the migration rather than silently picking one value.
do $$
declare
  n_bad integer;
begin
  select count(*) into n_bad from (
    select g.province_code
    from fact_uuc_phc_indicators i
    join dim_geo g on g.geo_code = i.geo_code
    group by g.province_code
    having count(distinct i.imr_prov_ref) > 1
        or count(distinct i.ufmr_prov_ref) > 1
        or count(distinct i.fic_prov_ref) > 1
        or count(distinct i.abr_prov_ref) > 1
        or count(distinct i.pre_natal_prov_ref) > 1
        or count(distinct i.sba_prov_ref) > 1
        or count(distinct i.water_prov_ref) > 1
  ) t;
  if n_bad > 0 then
    raise exception 'ref_uuc_phc_provincial would be ambiguous: % province(s) carry more than one provincial reference value', n_bad;
  end if;
end $$;
